# z-score with the mean/std of the TRAINING events; None = no standardisation.
FEATURE_MEAN = [0.2379, 13.866287085677053, 0.004736679970035981, 418.5339421422948, 55.681550658893244, 2.97957, 377.50135834003066, 579.8804386003983, 0.4729, 222.27425504912284, 0.4622993168303346, 2.4449750290229533]
